import{z as i,x as n,o as s,c as d,q as B,j as o,D as E,d as l,s as t,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"ABI 与代码生成","description":"","frontmatter":{"title":"ABI 与代码生成","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/abi-codegen.md","filePath":"cs/abi-codegen.md","lastUpdated":1791413859000}'),p={name:"cs/abi-codegen.md"};function c(I,a,D,m,S,C){const A=n("Mermaid");return s(),d("div",null,[a[2]||(a[2]=B('<h1 id="abi-与代码生成" tabindex="-1">ABI 与代码生成 <a class="header-anchor" href="#abi-与代码生成" aria-label="Permalink to &quot;ABI 与代码生成&quot;">​</a></h1><div class="epigraph"><p>应用程序二进制接口规定寄存器谁保存、参数怎么传、栈帧怎么长；代码生成必须按同一份文档发指令，函数才能跨编译单元互调。</p><footer>—— 据 System V Application Binary Interface, AMD64 Architecture Processor Supplement；RISC-V ELF psABI 整理</footer></div><p>上一课<a href="/cs/peephole">窥孔与窥视窗</a>清理了函数体内的短序列。<a href="/cs/calling-convention-stack">调用约定与栈</a>在组成课已讲帧与返回地址；<a href="/cs/riscv-int-isa">RISC-V 整数指令</a>已给出 <code>jal</code>/<code>jalr</code> 与整数寄存器名。本课不重画五级流水线。缺口是：把那些硬件事实<strong>写成跨编译器的合同</strong>——哪几个是参数寄存器、哪几个 callee-save、栈对齐、谁清参数区——并在序言/尾声里真正发射。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>着色已选物理寄存器，但「<code>x10</code> 是第一个整数参数」不是 ISA 强制，是 ABI。两个目标文件若一个把返回值放 <code>x10</code>、一个去栈上找，链接起来仍崩。缺口是代码生成器遵守一份 ABI 文本：System V AMD64 或 RISC-V psABI，而不是发明第四种约定。</p><p>序言：保存返回地址与 callee-save、调整 <code>sp</code>、对齐。尾声：恢复、返回。可变参数、结构体返回按文档走间接。本课不重讲异常入口。</p><h3 id="abi-不是-isa-子集" tabindex="-1">ABI 不是 ISA 子集 <a class="header-anchor" href="#abi-不是-isa-子集" aria-label="Permalink to &quot;ABI 不是 ISA 子集&quot;">​</a></h3><p>ISA 说指令编码；ABI 说软件约定。无 ABI 的「合法机器码」仍无法与 libc 互调。组成课的调用约定课给了栈直觉；本课把寄存器号与对齐钉到可汇编。</p><p><span class="marginnote">System V AMD64 ABI 与 RISC-V ELF psABI 是平台文档。本课引用它们的规则层级，不抄整张寄存器表。</span></p><p><span class="marginnote">术语翻译：callee-save（被调者保存）寄存器就是「谁想用谁先备份」的寄存器——函数 B 若要动它，必须先把旧值存进栈、返回前恢复。与之相对的 caller-save 则由调用方在 call 之前自己备份。分工写死在 ABI 里，两边才不会都以为对方保存了。</span></p><p><span class="marginnote">常见误区：初学者容易以为「同一 ISA 编译出的目标文件就能互相链接」。实际上 Windows x64 与 Linux 的 System V 都是 x86-64、指令编码相同，但参数放哪些寄存器、栈怎么对齐、异常怎么展开完全不同——ISA 相同、ABI 不同，照样链接崩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按目标选 ABI。参数：前几个进规定寄存器，其余入栈。生成 call：把实参挪到合同位置，<code>jal</code>/<code>call</code>。被调者按合同保存。栈槽给溢出与局部，对齐 16 字节等条款写进帧布局。</p>',13)),(s(),o(r,null,{default:E(()=>[t(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRCALL%5B%22IR%20call%22%5D%20--%3E%20ABI%5B%22psABI%20%2F%20SysV%20%E5%90%88%E5%90%8C%22%5D%0A%20%20ABI%20--%3E%20ARG%5B%22%E5%8F%82%E6%95%B0%E5%AF%84%E5%AD%98%E5%99%A8%E6%88%96%E6%A0%88%22%5D%0A%20%20ABI%20--%3E%20PRO%5B%22%E5%BA%8F%E8%A8%80%20%2F%20%E5%B0%BE%E5%A3%B0%22%5D%0A%20%20PRO%20--%3E%20OBJ%5B%22%E5%8F%AF%E9%87%8D%E5%AE%9A%E4%BD%8D%E6%8C%87%E4%BB%A4%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[l("窥孔不得破坏合同处的 "),e("code",null,"sp"),l(" 与保存集。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"同一 ISA、不同 OS 可以不同 ABI（Windows x64 对 System V）。交叉编译必须选对三元组。叶子函数可简化序言，仍须对齐与红区规则（若文档有红区）。本课点名，不把红区当所有目标的默认。",-1)),a[6]||(a[6]=e("p",null,"与特权级、系统调用号：那是另一份 ABI（syscall ABI），后课操作系统再接；本课是用户态函数调用。",-1)),a[7]||(a[7]=e("p",null,"第一张图画的是编译期：IR call 如何按合同落到指令。这张图回答第二个问题：运行时一次调用里，调用者与被调者按合同各干各的活，帧是怎么长出来又收回去的。",-1)),(s(),o(r,null,{default:E(()=>[t(A,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALLER%5B%22%E8%B0%83%E7%94%A8%E8%80%85%22%5D%20--%3E%20PUT%5B%22%E5%AE%9E%E5%8F%82%E6%8C%AA%E8%BF%9B%E5%90%88%E5%90%8C%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20PUT%20--%3E%20JAL%5B%22call%20%E8%B7%B3%E8%BD%AC%EF%BC%8C%E5%8E%8B%E5%85%A5%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%22%5D%0A%20%20JAL%20--%3E%20PRO%5B%22%E8%A2%AB%E8%B0%83%E8%80%85%E5%BA%8F%E8%A8%80%EF%BC%9A%E4%BF%9D%E5%AD%98%20callee-save%EF%BC%8C%E5%AF%B9%E9%BD%90%20sp%22%5D%0A%20%20PRO%20--%3E%20BODY%5B%22%E5%87%BD%E6%95%B0%E4%BD%93%22%5D%0A%20%20BODY%20--%3E%20EPI%5B%22%E5%B0%BE%E5%A3%B0%EF%BC%9A%E6%8C%89%E5%8E%9F%E6%A0%B7%E6%81%A2%E5%A4%8D%E5%AF%84%E5%AD%98%E5%99%A8%E4%B8%8E%20sp%22%5D%0A%20%20EPI%20--%3E%20RET%5B%22ret%EF%BC%8C%E8%BF%94%E5%9B%9E%E5%80%BC%E5%9C%A8%E5%90%88%E5%90%8C%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20RET%20--%3E%20BACK%5B%22%E8%B0%83%E7%94%A8%E8%80%85%E4%BB%8E%E4%B8%8B%E4%B8%80%E6%9D%A1%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=B('<p><span class="marginnote">数字实例：System V AMD64 要求 call 那一刻栈按 16 字节对齐。调用者进入时 sp 是 16 的倍数，call 压 8 字节返回地址后被调者序言再压一个寄存器（又 8 字节），sp 回到对齐——序言里少存一个寄存器，后面的对齐访存指令就可能当场崩溃。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解析 ELF 重定位项、不加载共享库。不实现完整 libc 启动（<code>_start</code>、<code>argc</code>）。后课默认：每个函数的入口出口遵守目标 ABI。链接把符号引用变成地址。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代码生成按 ABI 放参数、保存寄存器、对齐栈。</li><li>先修：调用约定课 + RISC-V 整数 ISA；合同文本是 SysV/psABI。</li><li>ISA 合法不等于能与其他目标文件互调。</li><li>出处：System V AMD64 ABI；RISC-V ELF psABI；Aho et al., 龙书第 7–8 章。</li></ul>',5))])}const b=i(p,[["render",c]]);export{u as __pageData,b as default};
